 if(rivers.empty())return {"empty","영토 안을 지나는 강이 없습니다."};
 Grid boundaryGrid(boundary,c.cell);const double tolerance=std::max(0.,c.merge);
 for(auto& river:rivers){check(cancelled);for(Point* endpoint:{&river.a,&river.b}){auto p=*endpoint;Bounds query{p.x-tolerance,p.y-tolerance,p.x+tolerance,p.y+tolerance};std::size_t nearest=boundary.size();double best=INFINITY,t=0;Point projected{};for(auto i:boundaryGrid.query(query)){const double parameterValue=std::clamp(parameter(p,boundary[i]),0.,1.);auto q=interpolate(boundary[i],parameterValue);const double d=distance(p,q);if(d>tolerance)continue;if(d<best||(d==best&&i<nearest)){nearest=i;best=d;t=parameterValue;projected=q;}}if(nearest<boundary.size()){*endpoint=projected;boundary[nearest].split.push_back(t);}}}
