V compose(const V& input){std::set<std::string> invalid;for(const auto& d:field(input,"donorResults").array)if(text(field(d,"status"))=="invalid"){auto id=text(field(d,"donorCountryId"));if(!id.empty())invalid.insert(id);}std::map<std::string,std::vector<V>> groups;for(const auto& c:field(input,"candidates").array){auto id=text(field(c,"donorCountryId")),key=text(field(c,"componentKey"));if(!id.empty()&&!key.empty()&&!invalid.count(id))groups[key].push_back(c);}for(auto& [key,rows]:groups)std::stable_sort(rows.begin(),rows.end(),[](const V& a,const V& b){return text(field(a,"key"))<text(field(b,"key"));});V items=V::arr(),ids=V::arr();std::size_t split=0,river=0;for(const auto& c:field(input,"components").array){auto id=text(field(c,"countryId"));if(id.empty())id=text(field(c,"donorCountryId"));if(id.empty()||invalid.count(id))continue;double index=number(field(c,"polygonIndex")),sourceIndex=number(field(c,"sourcePolygonIndex"),index);auto key=text(field(c,"componentKey"));if(key.empty())key=id+":"+text(V::num(index));auto found=groups.find(key);const bool partition=found!=groups.end()&&!found->second.empty();auto emit=[&](V row){row.object["countryId"]=V::str(id);row.object["polygonIndex"]=V::num(index);row.object["sourcePolygonIndex"]=V::num(sourceIndex);row.object["componentKey"]=V::str(key);row.object["partitionKind"]=V::str(partition?"river":"original");items.array.push_back(std::move(row));};if(partition){++split;river+=found->second.size();for(const auto& row:found->second)emit(row);}else emit(c);}for(const auto& id:invalid)ids.array.push_back(V::str(id));return obj({{"items",items},{"invalidDonorIds",ids},{"splitComponentCount",V::num(double(split))},{"riverCandidateCount",V::num(double(river))}});}
