V observe(const V& input){V rows=V::arr();for(const auto& donor:field(input,"donors").array){auto ps=polygons(field(donor,"geometry"));for(std::size_t i=0;i<ps.size();++i){const auto& p=ps[i];Workspace w(p);V samples=V::arr();const auto& features=field(input,"riverFeatures").array;for(std::size_t j=0;j<std::min<std::size_t>(2,features.size());++j){const auto& f=features[j];auto parts=lines(field(f,"geometry"));const auto type=text(field(field(f,"geometry"),"type"));if(type!="LineString"&&type!="MultiLineString")continue;V points=V::arr();if(!parts.empty())for(std::size_t k=0;k<std::min<std::size_t>(2,parts[0].size());++k){auto q=parts[0][k];points.array.push_back(obj({{"input",json(q)},{"meters",json(w.meters(q))}}));}samples.array.push_back(obj({{"id",V::str(text(field(field(f,"properties"),"pandolab_id"),text(field(f,"id"))))},{"points",points}}));}V first;if(!p.empty()&&!p[0].empty())first=obj({{"input",json(p[0][0])},{"meters",json(w.meters(p[0][0]))}});rows.array.push_back(obj({{"donorId",field(donor,"countryId")},{"componentIndex",V::num(double(i))},{"centerLongitude",V::num(w.longitude)},{"centerLatitude",V::num(w.latitude)},{"angle",V::num(w.latitude*rad)},{"cosine",V::num(std::cos(w.latitude*rad))},{"cosineScale",V::num(w.cosine)},{"firstPoint",first},{"riverSamples",samples}}));}}return rows;}
