double riverSphericalAreaKm2(const Geometry& input,const GeometryCancellation& cancelled){
    const auto check=[&]{if(cancelled&&cancelled())throw PolygonCalculationCancelled{};};check();
    if((input.type!="Polygon"&&input.type!="MultiPolygon")||(input.type=="Polygon"&&input.polygons.size()!=1)||!input.lines.empty()||!input.points.empty())throw std::invalid_argument("RIVER_AREA_INVALID_POLYGON_GEOMETRY");
    for(const auto& polygon:input.polygons){check();if(polygon.empty())throw std::invalid_argument("RIVER_AREA_EMPTY_POLYGON");for(const auto& ring:polygon){
        if(ring.size()<4||ring.front().x!=ring.back().x||ring.front().y!=ring.back().y)throw std::invalid_argument("RIVER_AREA_INVALID_RING");
        for(auto p:ring){check();if(!std::isfinite(p.x)||!std::isfinite(p.y)||std::abs(p.x)>180||std::abs(p.y)>90)throw std::invalid_argument("RIVER_AREA_INVALID_COORDINATE");}
    }}
    check();const double area=std::max(0.,sphericalPolygonArea(input,cancelled)*(6371.0088*6371.0088));check();
    if(!std::isfinite(area))throw std::runtime_error("RIVER_AREA_NONFINITE_RESULT");return area;
}
